import { readFileSync, writeFileSync } from 'node:fs';

const path='infrastructure/upgrades/launch-readiness-v2/tests/final-review.test.mjs';
const value=readFileSync(path,'utf8');
const before="test('Google runtime deployment replaces env and secret sets',()=>{const target={appwrite:{endpoint:'https://syd.cloud.appwrite.io/v1',projectId:'p',databaseId:'proinspect_core'},google:{environment:'staging',projectId:'g-project',runtimeBindings:{api:{env:{AUTH_PROVIDER:'appwrite',APPWRITE_BACKEND_MODE:'appwrite'},secretRefs:{APPWRITE_API_KEY:'appwrite-api:1'}}}}};const args=runtimeArguments(target,'api','a'.repeat(40));assert(args.includes('--set-env-vars'));assert(args.includes('--set-secrets'));assert(!args.includes('--update-env-vars'));assert(!args.includes('--update-secrets'));const env=args[args.indexOf('--set-env-vars')+1];assert.match(env,/APP_ENV=staging/);assert.match(env,/GOOGLE_CLOUD_PROJECT=g-project/);});";
const after="test('Google runtime deployment updates launch-owned env and secret bindings',()=>{const target={appwrite:{endpoint:'https://syd.cloud.appwrite.io/v1',projectId:'p',databaseId:'proinspect_core'},google:{environment:'staging',projectId:'g-project',runtimeBindings:{api:{env:{AUTH_PROVIDER:'appwrite',APPWRITE_BACKEND_MODE:'appwrite'},secretRefs:{APPWRITE_API_KEY:'appwrite-api:1'}}}}};const args=runtimeArguments(target,'api','a'.repeat(40));assert(args.includes('--update-env-vars'));assert(args.includes('--update-secrets'));assert(!args.includes('--set-env-vars'));assert(!args.includes('--set-secrets'));assert(!args.includes('--clear-secrets'));const env=args[args.indexOf('--update-env-vars')+1];assert.match(env,/APP_ENV=staging/);assert.match(env,/GOOGLE_CLOUD_PROJECT=g-project/);});";
if(!value.includes(before)) throw new Error('Missing stale Google runtime regression assertion');
if(value.indexOf(before)!==value.lastIndexOf(before)) throw new Error('Non-unique stale Google runtime regression assertion');
writeFileSync(path,value.replace(before,after));
console.log('Updated V2.6 Google runtime regression contract.');
